-- patron_author_report.sql
-- Generated by bft-maker
-- BFT table: Patron x Book x Author
-- Metrics:
--   membership_fee (Patron) allocation for Book, allocation for Author
--   fine_amount (Checkout) allocation for Author
--   replacement_cost (Book) elimination for Patron, reserve for Author
--   hold_count (Hold) reserve for Author
--   avg_fine_per_checkout (Patron) sum_over_sum for Book, reserve for Author

-----------------------------------------------------------------------
-- Step 1: Base grain (Patron x Book x Author)
-----------------------------------------------------------------------
CREATE OR REPLACE TABLE "par_base" AS
SELECT
    p."patron_id",
    p."name" AS "patron_name",
    p."membership_fee",
    p."avg_fine_per_checkout",
    b."book_id",
    b."name" AS "book_name",
    b."replacement_cost",
    a."author_id",
    a."name" AS "author_name",
    c."fine_amount"
FROM "patrons" p
JOIN "checkouts" c ON p."patron_id" = c."patron_id"
JOIN "books" b ON b."book_id" = c."book_id"
JOIN "book_authors" b2 ON b."book_id" = b2."book_id"
JOIN "authors" a ON a."author_id" = b2."author_id";

-----------------------------------------------------------------------
-- Step 2: Compute weights for allocation / sum_over_sum
-----------------------------------------------------------------------
CREATE OR REPLACE TABLE "par_weighted" AS
SELECT
    *,
    COUNT(DISTINCT "book_id") OVER (PARTITION BY "patron_id") AS "checkout_count",
    COUNT(DISTINCT "author_id") OVER (PARTITION BY "patron_id", "book_id") AS "bookauthor_count"
FROM "par_base";

-----------------------------------------------------------------------
-- Step 3: Assemble final table
-----------------------------------------------------------------------
CREATE OR REPLACE TABLE "patron_author_report" AS

-- base base rows
SELECT
    "patron_id",
    "patron_name",
    "book_id",
    "book_name",
    "author_id",
    "author_name",
    "membership_fee" * 1.0 / "checkout_count" / "bookauthor_count" AS "membership_fee",
    "fine_amount" * 1.0 / "bookauthor_count" AS "fine_amount",
    0.0 AS "replacement_cost",
    0.0 AS "hold_count",
    "avg_fine_per_checkout",
    1.0 / "checkout_count" AS "avg_fine_per_checkout_weight"
FROM "par_weighted"

UNION ALL

-- replacement_cost propagation data rows
SELECT DISTINCT
    "patron_id",
    "patron_name",
    "book_id",
    "book_name",
    NULL AS "author_id",
    '<Unallocated>' AS "author_name",
    0.0 AS "membership_fee",
    0.0 AS "fine_amount",
    "replacement_cost" * 1.0 AS "replacement_cost",
    0.0 AS "hold_count",
    0.0 AS "avg_fine_per_checkout",
    0 AS "avg_fine_per_checkout_weight"
FROM "par_weighted"

UNION ALL

-- replacement_cost elimination correction (hop 0)
SELECT
    NULL AS "patron_id",
    '<Unallocated>' AS "patron_name",
    "book_id",
    "book_name",
    NULL AS "author_id",
    '<Unallocated>' AS "author_name",
    0 AS "membership_fee",
    0 AS "fine_amount",
    "replacement_cost" * (1 - COUNT(DISTINCT "patron_id")) AS "replacement_cost",
    0 AS "hold_count",
    0 AS "avg_fine_per_checkout",
    0 AS "avg_fine_per_checkout_weight"
FROM "par_base"
GROUP BY "book_id", "book_name", "replacement_cost"

UNION ALL

-- Reserve placeholder rows for hold_count
SELECT
    "patron_id",
    "name" AS "patron_name",
    NULL AS "book_id",
    '<Unallocated>' AS "book_name",
    NULL AS "author_id",
    '<Unallocated>' AS "author_name",
    0.0 AS "membership_fee",
    0.0 AS "fine_amount",
    0.0 AS "replacement_cost",
    "hold_count" * 1.0 AS "hold_count",
    0.0 AS "avg_fine_per_checkout",
    0 AS "avg_fine_per_checkout_weight"
FROM "patrons";

-----------------------------------------------------------------------
-- Validation
-----------------------------------------------------------------------

-- V1: SUM(membership_fee) matches source
SELECT 'V1 membership_fee_sum' AS test,
       CASE WHEN ABS(SUM("membership_fee") - (SELECT SUM("membership_fee") FROM "patrons")) < 0.01
            THEN 'PASS' ELSE 'FAIL: ' || SUM("membership_fee") END AS result
FROM "patron_author_report";

-- V2: SUM(fine_amount) matches source
SELECT 'V2 fine_amount_sum' AS test,
       CASE WHEN ABS(SUM("fine_amount") - (SELECT SUM("fine_amount") FROM "checkouts")) < 0.01
            THEN 'PASS' ELSE 'FAIL: ' || SUM("fine_amount") END AS result
FROM "patron_author_report";

-- V3: SUM(replacement_cost) matches source
SELECT 'V3 replacement_cost_sum' AS test,
       CASE WHEN ABS(SUM("replacement_cost") - (SELECT SUM("replacement_cost") FROM "books")) < 0.01
            THEN 'PASS' ELSE 'FAIL: ' || SUM("replacement_cost") END AS result
FROM "patron_author_report";

-- V4: SUM(hold_count) matches source
SELECT 'V4 hold_count_sum' AS test,
       CASE WHEN ABS(SUM("hold_count") - (SELECT SUM("hold_count") FROM "holds")) < 0.01
            THEN 'PASS' ELSE 'FAIL: ' || SUM("hold_count") END AS result
FROM "patron_author_report";

-- V5: membership_fee per Patron sums to original
SELECT 'V5 membership_fee_per_patron' AS test,
       CASE WHEN COUNT(*) = 0 THEN 'PASS'
            ELSE 'FAIL: ' || COUNT(*) || ' with wrong sum' END AS result
FROM (
    SELECT t."patron_id", ABS(SUM(t."membership_fee") - s."membership_fee") AS err
    FROM "patron_author_report" t
    JOIN "patrons" s ON t."patron_id" = s."patron_id"
    GROUP BY t."patron_id", s."membership_fee"
    HAVING ABS(SUM(t."membership_fee") - s."membership_fee") > 0.01
);